/**
 * The logo, as the Worker serves it. Embedded so a deployment needs no static asset hosting.
 * Source: a speech bubble with a search lens, for "search your chats". The PNGs are renders of the SVG.
 */
export const FAVICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
  <rect id="body" x="32" y="32" width="448" height="448" rx="104" fill="#0B5D4B"/>
  <g id="icon">
    <rect x="84" y="92" width="344" height="256" rx="82" fill="#FFFFFF"/>
    <path d="M134 328 L122 418 L226 340 Z" fill="#FFFFFF"/>
    <circle cx="230" cy="214" r="64" fill="#5FD1A8" stroke="#0B5D4B" stroke-width="36"/>
    <path d="M282 266 L334 318" stroke="#0B5D4B" stroke-width="40" stroke-linecap="round"/>
  </g>
</svg>`;

const bytes = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const FAVICON_32 = bytes('');
export const APPLE_TOUCH_ICON = bytes('');
